SELECT p.*, s.name AS shop_name, s.score AS shop_score
FROM products p JOIN shops s ON p.shop_id = s.shop_id
WHERE p.deleted = 0 AND p.on_sale = 1
 AND p.shop_id = #{shopId} 
 AND p.category = #{category} 
 AND p.sub = #{sub} 
 AND p.title LIKE CONCAT('%', #{keyword}, '%') 


    ORDER BY p.sales DESC, p.created_at DESC
    ORDER BY p.price ASC, p.created_at DESC
    ORDER BY p.price DESC, p.created_at DESC
    ORDER BY p.created_at DESC

LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM products p
WHERE p.deleted = 0 AND p.on_sale = 1
 AND p.category = #{category} 
 AND p.sub = #{sub} 
 AND p.shop_id = #{shopId} 
 AND p.title LIKE CONCAT('%', #{keyword}, '%')

SELECT p.*, s.name AS shop_name, s.score AS shop_score
FROM products p JOIN shops s ON p.shop_id = s.shop_id
WHERE p.deleted = 0 AND p.on_sale = 1 AND p.id != #{id}
ORDER BY (p.category = #{category}) DESC, p.sales DESC, p.created_at DESC
LIMIT #{limit}

SELECT p.*, s.name AS shop_name, s.score AS shop_score FROM products p JOIN shops s ON p.shop_id = s.shop_id WHERE p.deleted = 0 AND p.on_sale = 1 AND p.title LIKE CONCAT('%', #{q}, '%')
ORDER BY p.sales DESC, p.created_at DESC ORDER BY p.price ASC, p.created_at DESC ORDER BY p.price DESC, p.created_at DESC ORDER BY p.sales DESC, p.created_at DESC
LIMIT #{offset}, #{size}
